import { useState, useEffect } from 'react';
import { getMyDashboard, getAdminDashboard } from '../api';
import { useAuth } from '../context/AuthContext';

// ─── Mini bar chart ──────────────────────────────────────────────────────────
function BarChart({ data, color, height = 60 }) {
  if (!data || !data.length) return null;
  const max = Math.max(...data.map(d => d.value), 1);
  return (
    <div style={{ display: 'flex', alignItems: 'flex-end', gap: 3, height, paddingTop: 4 }}>
      {data.map((d, i) => (
        <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2, height: '100%', justifyContent: 'flex-end' }}>
          <div
            title={`${d.date}: ${d.value.toLocaleString()}`}
            style={{
              width: '100%', borderRadius: '3px 3px 0 0',
              background: d.value > 0 ? color : 'var(--bg4)',
              height: `${Math.max((d.value / max) * 100, d.value > 0 ? 8 : 4)}%`,
              transition: 'height 0.3s ease',
              opacity: 0.85,
              cursor: 'default',
            }}
          />
        </div>
      ))}
    </div>
  );
}

// ─── Stat card ───────────────────────────────────────────────────────────────
function StatCard({ label, today, week, month, total, color, chart, sub }) {
  const [period, setPeriod] = useState('today');
  const vals = { today, week, month };
  return (
    <div style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '20px 22px', boxShadow: 'var(--shadow-sm)' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 14 }}>
        <div>
          <div style={{ fontSize: 11, fontFamily: 'DM Mono', color: 'var(--text-dim)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 6 }}>{label}</div>
          <div style={{ fontFamily: 'Syne', fontSize: 30, fontWeight: 700, letterSpacing: '-0.03em', color: color || 'var(--text)', lineHeight: 1 }}>
            {(vals[period] || 0).toLocaleString()}
          </div>
          {total !== undefined && <div style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono', marginTop: 4 }}>All time: {total.toLocaleString()}</div>}
          {sub && <div style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono', marginTop: 4 }}>{sub}</div>}
        </div>
        <div style={{ display: 'flex', gap: 2, background: 'var(--bg3)', border: '1px solid var(--border)', borderRadius: 8, padding: 2 }}>
          {['today', 'week', 'month'].map(p => (
            <button key={p} onClick={() => setPeriod(p)}
              style={{ background: period === p ? 'var(--bg2)' : 'transparent', color: period === p ? 'var(--text)' : 'var(--text-dim)', border: period === p ? '1px solid var(--border-mid)' : '1px solid transparent', padding: '4px 8px', borderRadius: 6, fontSize: 10, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer', textTransform: 'capitalize' }}>
              {p}
            </button>
          ))}
        </div>
      </div>
      {chart && <BarChart data={chart} color={color || 'var(--accent)'} height={50} />}
    </div>
  );
}

// ─── Activity row ─────────────────────────────────────────────────────────────
function ActivityRow({ item, showUser }) {
  const time = item.sent_at ? new Date(item.sent_at).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—';
  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 0', borderBottom: '1px solid var(--border)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <div style={{ width: 32, height: 32, background: 'var(--green-bg)', border: '1px solid var(--green-border)', borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14 }}>📨</div>
        <div>
          {showUser && <div style={{ fontSize: 12, fontWeight: 500, marginBottom: 1 }}>{item.user_name || item.user_email}</div>}
          <div style={{ fontSize: 12, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>
            Batch {item.batch_number}/{item.total_batches} · {item.email_count} emails
          </div>
          {item.subject && <div style={{ fontSize: 11, color: 'var(--text-dim)', marginTop: 1 }}>"{item.subject}"</div>}
        </div>
      </div>
      <div style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono', textAlign: 'right' }}>{time}</div>
    </div>
  );
}

// ─── Top users table ──────────────────────────────────────────────────────────
function TopUsers({ users }) {
  if (!users?.length) return <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-dim)', fontSize: 13 }}>No data yet</div>;
  const max = users[0]?.total || 1;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      {users.map((u, i) => (
        <div key={u.user_id} style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <div style={{ width: 22, fontFamily: 'Syne', fontWeight: 700, fontSize: 13, color: i < 3 ? 'var(--amber)' : 'var(--text-dim)', textAlign: 'center' }}>
            {i + 1}
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
              <span style={{ fontSize: 13, fontWeight: 500 }}>{u.name || u.email}</span>
              <span style={{ fontSize: 12, fontFamily: 'DM Mono', color: 'var(--text-muted)' }}>{u.total.toLocaleString()}</span>
            </div>
            <div style={{ height: 5, background: 'var(--bg3)', borderRadius: 99, overflow: 'hidden' }}>
              <div style={{ height: '100%', width: `${(u.total / max) * 100}%`, background: i === 0 ? 'var(--amber)' : 'var(--green)', borderRadius: 99 }} />
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────
export default function Dashboard() {
  const { user } = useAuth();
  const isAdmin  = ['admin', 'main_admin'].includes(user?.role);
  const [view, setView]     = useState(isAdmin ? 'admin' : 'me');
  const [data, setData]     = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError]   = useState('');

  const load = async () => {
    setLoading(true); setError('');
    try {
      const d = view === 'admin' ? await getAdminDashboard() : await getMyDashboard();
      setData(d);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [view]);

  return (
    <div style={{ maxWidth: 960, margin: '0 auto', padding: '32px 28px 80px' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 28 }}>
        <div>
          <h1 style={{ fontFamily: 'Syne', fontSize: 24, fontWeight: 700, letterSpacing: '-0.03em', marginBottom: 4 }}>
            {view === 'admin' ? 'Platform overview' : `Hey ${user?.name?.split(' ')[0]} 👋`}
          </h1>
          <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>
            {view === 'admin' ? 'Monitor all users and platform activity' : 'Your verification and scout activity'}
          </p>
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {isAdmin && (
            <div style={{ display: 'flex', gap: 2, background: 'var(--bg3)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: 3 }}>
              {['me', 'admin'].map(v => (
                <button key={v} onClick={() => setView(v)}
                  style={{ background: view === v ? 'var(--bg2)' : 'transparent', color: view === v ? 'var(--text)' : 'var(--text-muted)', border: view === v ? '1px solid var(--border-mid)' : '1px solid transparent', padding: '7px 16px', borderRadius: 8, fontFamily: 'Syne', fontWeight: 600, fontSize: 12, cursor: 'pointer' }}>
                  {v === 'me' ? 'My stats' : 'Platform'}
                </button>
              ))}
            </div>
          )}
          <button onClick={load} className="btn-ghost" style={{ padding: '8px 16px', fontSize: 12 }}>↻ Refresh</button>
        </div>
      </div>

      {loading && (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '80px 0', gap: 12, color: 'var(--text-muted)', fontSize: 13 }}>
          <span className="spinner" style={{ fontSize: 20 }}>↻</span> Loading dashboard...
        </div>
      )}

      {error && (
        <div style={{ background: 'var(--red-bg)', border: '1px solid var(--red-border)', borderRadius: 'var(--radius)', padding: '14px 18px', color: 'var(--red)', fontSize: 13, marginBottom: 20 }}>{error}</div>
      )}

      {/* ── MY STATS view ── */}
      {!loading && data && view === 'me' && (
        <div className="animate-in">

          {/* Stat cards */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14, marginBottom: 20 }}>
            <StatCard
              label="Emails verified"
              today={data.verified?.today} week={data.verified?.week} month={data.verified?.month} total={data.verified?.total}
              color="var(--blue)" chart={data.verify_series}
            />
            <StatCard
              label="Emails scouted"
              today={data.scouted?.today} week={data.scouted?.week} month={data.scouted?.month} total={data.scouted?.total}
              color="var(--green)" chart={data.scout_series}
              sub={`${data.scouted?.batches_sent || 0} total batches sent`}
            />
          </div>

          {/* Quick insight strip */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 12, marginBottom: 24 }}>
            {[
              { label: 'Scout rate', value: data.verified?.total ? `${Math.round((data.scouted?.total / data.verified.total) * 100)}%` : '—', sub: 'of verified emails scouted', color: 'var(--amber)' },
              { label: 'Batches sent', value: data.scouted?.batches_sent || 0, sub: 'total email batches', color: 'var(--green)' },
              { label: 'This month verified', value: (data.verified?.month || 0).toLocaleString(), sub: 'emails checked', color: 'var(--text)' },
            ].map(s => (
              <div key={s.label} style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '16px 20px', boxShadow: 'var(--shadow-sm)' }}>
                <div style={{ fontSize: 11, fontFamily: 'DM Mono', color: 'var(--text-dim)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 6 }}>{s.label}</div>
                <div style={{ fontFamily: 'Syne', fontSize: 22, fontWeight: 700, color: s.color, letterSpacing: '-0.02em' }}>{s.value}</div>
                <div style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono', marginTop: 3 }}>{s.sub}</div>
              </div>
            ))}
          </div>

          {/* Recent activity */}
          <div style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '20px 24px', boxShadow: 'var(--shadow-sm)' }}>
            <div style={{ fontFamily: 'Syne', fontSize: 14, fontWeight: 700, marginBottom: 16, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              Recent scout activity
              <span style={{ fontSize: 11, fontFamily: 'DM Mono', color: 'var(--text-dim)', fontWeight: 400 }}>Last 10 batches</span>
            </div>
            {data.recent_activity?.length ? (
              data.recent_activity.map((item, i) => <ActivityRow key={i} item={item} showUser={false} />)
            ) : (
              <div style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-dim)', fontSize: 13 }}>
                No scout activity yet. Verify some emails and start scouting!
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── ADMIN view ── */}
      {!loading && data && view === 'admin' && (
        <div className="animate-in">

          {/* User stat strip */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 12, marginBottom: 20 }}>
            {[
              { label: 'Total users', value: data.users?.total || 0, color: 'var(--text)', sub: 'registered accounts' },
              { label: 'Pending approval', value: data.users?.pending || 0, color: 'var(--amber)', sub: 'waiting for access' },
              { label: 'Active users', value: data.users?.approved || 0, color: 'var(--green)', sub: 'approved accounts' },
            ].map(s => (
              <div key={s.label} style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '18px 22px', boxShadow: 'var(--shadow-sm)' }}>
                <div style={{ fontSize: 11, fontFamily: 'DM Mono', color: 'var(--text-dim)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 6 }}>{s.label}</div>
                <div style={{ fontFamily: 'Syne', fontSize: 28, fontWeight: 700, color: s.color, letterSpacing: '-0.02em' }}>{s.value}</div>
                <div style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono', marginTop: 3 }}>{s.sub}</div>
              </div>
            ))}
          </div>

          {/* Platform stat cards */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14, marginBottom: 20 }}>
            <StatCard
              label="Platform verifications"
              today={data.verified?.today} week={data.verified?.week} month={data.verified?.month}
              color="#6366f1" chart={data.verify_series}
            />
            <StatCard
              label="Platform emails scouted"
              today={data.scouted?.today} week={data.scouted?.week} month={data.scouted?.month}
              color="var(--green)" chart={data.scout_series}
            />
          </div>

          {/* Bottom grid — top users + recent activity */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>

            {/* Top scouts this month */}
            <div style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '20px 24px', boxShadow: 'var(--shadow-sm)' }}>
              <div style={{ fontFamily: 'Syne', fontSize: 14, fontWeight: 700, marginBottom: 16, display: 'flex', justifyContent: 'space-between' }}>
                Top scouts this month
                <span style={{ fontSize: 11, fontFamily: 'DM Mono', color: 'var(--text-dim)', fontWeight: 400 }}>by emails scouted</span>
              </div>
              <TopUsers users={data.top_users} />
            </div>

            {/* Recent activity */}
            <div style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '20px 24px', boxShadow: 'var(--shadow-sm)', overflowY: 'auto', maxHeight: 400 }}>
              <div style={{ fontFamily: 'Syne', fontSize: 14, fontWeight: 700, marginBottom: 16, display: 'flex', justifyContent: 'space-between' }}>
                Live activity feed
                <span style={{ fontSize: 11, fontFamily: 'DM Mono', color: 'var(--text-dim)', fontWeight: 400 }}>Last 20 actions</span>
              </div>
              {data.recent_activity?.length ? (
                data.recent_activity.map((item, i) => <ActivityRow key={i} item={item} showUser={true} />)
              ) : (
                <div style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-dim)', fontSize: 13 }}>No activity yet</div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
